G.deathAnims.push({x:e.x,y:e.y,r:Math.max(8,Math.min(48,e.r||14)),face:+e.face||0,c:DEATH_COL[e.kind]||'#555c64',t0:G.t||0,kind:e.kind||''});
// v23.xx (gfx17), HIS ORDER (2026-10-12) on the graphics program, item 3, the animation pass: a dying human keeps his look,
// his build and his side, so the fall below is drawn as him, in every window (a linked window builds e from the death word).
if(e.kind==='raider'||e.kind==='stray') G.deathAnims[G.deathAnims.length-1].hum={coat:e.coat||'#4a4438',build:e.build,hair:e.hair,cut:e.cut,hat:e.hat,
  skin:e.skin,beard:e.beard,eyes:e.eyes,faceMark:e.faceMark,boots:e.boots,gloves:e.gloves,pack:e.pack,patch:e.patch,tattoo:e.tattoo,
  team:(e.kind==='raider')?'foe':null,down:(e.downed||e.state==='down')?1:0};

for(i=G.deathAnims.length-1;i>=0;i--){
  a=G.deathAnims[i];
  // v23.xx (gfx17), HIS ORDER (2026-10-12), item 3: HUMANS FALL. A pillager who died used to leave the same turning ellipse
  // as a machine. Now his own body falls: the downed figure (gfx16), in his look and build, pivots about his boots from
  // upright to the ground over 0.35 seconds, falling faster as it goes, lies still and then fades out over the body bag
  // he left, gone at 1.6 seconds. One already down when he died does not fall again. Machines keep the ellipse.
  if(a.hum){
    f=(G.t||0)-a.t0;
    if(!(f>=0&&f<1.6)){ G.deathAnims.splice(i,1); continue; }
    var _dfl=Math.cos(a.face)<0?-1:1, _dfa=a.hum.down?1:Math.min(1,f/0.35), _dst={hero:0}, _dk;
    for(_dk in a.hum) _dst[_dk]=a.hum[_dk];
    wc.save(); wc.globalAlpha=(f<1.0)?1:Math.max(0,1-(f-1.0)/0.6);
    wc.translate(a.x-_dfl*16,a.y); wc.rotate(-_dfl*(1-_dfa*_dfa)*1.45);
    try{ drawOp(_dfl*16,0,a.face,0,a.hum.coat,0,0,'down',0,_dst); }catch(_dop){}
    wc.restore();
    continue;
  }
  f=((G.t||0)-a.t0)/0.8;

