{v:'VER',what:'graphics program gfx17 (humans fall): a pillager who dies is drawn as his own downed body in his build, pivoting from upright to the ground over 0.35 seconds and gone by 1.7; one already down does not fall; a crawler keeps the ellipse',
 run:function(){
   if(typeof deathAnimAdd!=='function'||typeof drawDeathAnims!=='function') return 'SKIP: no death animation here';
   if(!window.__deploy||!window.__endRaid) return 'SKIP: no raid in this fixture';
   var bad=[], od=drawOp, calls=[], rots=[], oRot, t0, s;
   try{
     __topClear(); __runPrep(); __resetCfg(); __pinDefaults(0); __cleanProfile();
     __deploy({kit:[],safe:null,mapIx:0,seed:4242});
     if(!G||G.over||!G.player) return 'SKIP: staging: no raid';
     G.deathAnims=[]; t0=G.t||0;
     deathAnimAdd({kind:'raider',x:G.player.x+60,y:G.player.y,r:11,face:0,coat:'#4a4438',build:'curved',hair:'dark',skin:'fair'});
     oRot=wc.rotate;
     wc.rotate=function(a){ rots.push(a); return oRot.apply(this,arguments); };
     drawOp=function(x,y,f,ph,co,pk,mu,mode,iv,st){ calls.push({mode:mode,build:st&&st.build,team:st&&st.team,rot:rots.length?rots[rots.length-1]:null}); return od.apply(this,arguments); };
     [0,0.15,0.3,0.6].forEach(function(dt){ G.t=t0+dt; rots.length=0; drawDeathAnims(); });
     drawOp=od; delete wc.rotate;
     if(calls.length<4) bad.push('the dying pillager was drawn '+calls.length+' times in 4 frames, not as his body');
     else {
       if(calls.some(function(c){ return c.mode!=='down'; })) bad.push('the falling body is not the downed pose');
       if(calls[0].build!=='curved') bad.push('the falling body lost his build');
       if(calls[0].team!=='foe') bad.push('the falling body lost his side');
       var r0=Math.abs(calls[0].rot||0), r1=Math.abs(calls[1].rot||0), r3=Math.abs(calls[3].rot||0);
       if(!(r0>1.2&&r1<r0&&r3<0.01)) bad.push('the body does not pivot from upright to the ground ('+r0.toFixed(2)+', '+r1.toFixed(2)+', '+r3.toFixed(2)+')');
     }
     G.t=t0+1.7; drawDeathAnims();
     if((G.deathAnims||[]).length) bad.push('the fallen body did not clear by 1.7 seconds');
     G.deathAnims=[]; calls.length=0; G.t=t0;
     deathAnimAdd({kind:'raider',x:G.player.x+60,y:G.player.y,r:11,face:0,coat:'#4a4438',downed:1,state:'down'});
     wc.rotate=function(a){ rots.push(a); return oRot.apply(this,arguments); };
     drawOp=function(x,y,f,ph,co,pk,mu,mode,iv,st){ calls.push({rot:rots.length?rots[rots.length-1]:null}); return od.apply(this,arguments); };
     rots.length=0; drawDeathAnims();
     drawOp=od; delete wc.rotate;
     if(!calls.length||Math.abs(calls[0].rot||0)>0.01) bad.push('a pillager already down falls again');
     G.deathAnims=[]; calls.length=0;
     deathAnimAdd({kind:'crawler',x:G.player.x+60,y:G.player.y,r:15,face:0});
     drawOp=function(){ calls.push(1); return od.apply(this,arguments); };
     drawDeathAnims(); drawOp=od;
     if(calls.length) bad.push('a crawler death is drawn as a human body');
   }catch(ex){ bad.push('threw: '+(ex&&ex.message||ex)); }
   finally{
     drawOp=od; try{ delete wc.rotate; }catch(_r){}
     try{ if(G){ G.deathAnims=[]; if(t0!==undefined) G.t=t0; } }catch(_d){}
     try{ __endRaid('abandon'); __topClear(); __cleanProfile(); }catch(_c){}
   }
   return bad.length?bad.join('; '):null; }},
